// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }

    function testFuzz_property(address nominee, address next) public {
        vm.assume(nominee != address(this));
        vm.assume(next != address(this));
        // Current owner (the test contract, deployer) nominates `nominee`.
        vm.prank(c.owner());
        c.setOwner(nominee);
        // General rule: the nominee must now be able to exercise ownership rights.
        bool ok;
        vm.prank(nominee);
        try c.setOwner(next) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}
